import{_ as t,a,c as o,ac as n}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第三册：培养技能 · Lesson 11 Not guilty","description":"学习 转述要求与否定命令，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第三册：培养技能 · Lesson 11 Not guilty","description":"学习 转述要求与否定命令，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第3册课时","summary":"学习 转述要求与否定命令，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第三册：培养技能 · Lesson 10 The loss of the Titanic","link":"/life/english/new-concept/book-3/unit-01/lesson-010"},"next":{"text":"第三册：培养技能 · Lesson 12 Life on a desert island","link":"/life/english/new-concept/book-3/unit-01/lesson-012"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第三册：培养技能 · Lesson 10 The loss of the Titanic","link":"/life/english/new-concept/book-3/unit-01/lesson-010"},"next":{"text":"第三册：培养技能 · Lesson 12 Life on a desert island","link":"/life/english/new-concept/book-3/unit-01/lesson-012"}},"headers":[],"relativePath":"life/english/new-concept/book-3/unit-01/lesson-011.md","filePath":"life/english/new-concept/book-3/unit-01/lesson-011.md"}'),i={name:"life/english/new-concept/book-3/unit-01/lesson-011.md"};function l(s,e,r,d,h,c){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="第三册-培养技能-·-lesson-11-not-guilty" tabindex="-1">第三册：培养技能 · Lesson 11 Not guilty <a class="header-anchor" href="#第三册-培养技能-·-lesson-11-not-guilty" aria-label="Permalink to &quot;第三册：培养技能 · Lesson 11 Not guilty&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-3/contents">本册目录</a> · <a href="/life/english/new-concept/book-3/unit-01/overview">单元 1</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>围绕检查、申报与解释误会，练习礼貌地报告自己说过的话和别人提出的要求。重点是准确保留信息，不靠“无辜”这一态度词代替事实。学习把直接命令转成不定式结构，并区分要求做某事、询问事实以及解释原因这三种言语行为。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>declare</td><td>/dɪˈkleə/</td><td>v.</td><td>申报</td><td>declare goods</td></tr><tr><td>inspect</td><td>/ɪnˈspekt/</td><td>v.</td><td>检查</td><td>inspect a bag</td></tr><tr><td>receipt</td><td>/rɪˈsiːt/</td><td>n.</td><td>收据</td><td>keep a receipt</td></tr><tr><td>explanation</td><td>/ˌekspləˈneɪʃən/</td><td>n.</td><td>解释</td><td>give an explanation</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>have nothing to declare — 没有需要申报的物品，须以实际规定为准</li><li>account for — 解释某事的原因或去向</li></ul><h2 id="语法讲解-转述要求与否定命令" tabindex="-1">语法讲解：转述要求与否定命令 <a class="header-anchor" href="#语法讲解-转述要求与否定命令" aria-label="Permalink to &quot;语法讲解：转述要求与否定命令&quot;">​</a></h2><p>tell 或 ask 加宾语再加 to do，可以转述要求；否定要求把 not 放在 to 前，如 asked me not to open it。tell 通常需要明确对象，不能写 told to me do。ask someone to do 与 ask someone whether ... 的结构不同，前者请求动作，后者询问信息。礼貌程度取决于上下文和措辞，并非只凭 ask 就一定温和。转述时还要调整代词，使读者清楚是谁收到要求、谁负责执行动作。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>The officer asked me to place the sealed box on the counter.</p></blockquote><p>工作人员让我把密封盒子放到柜台上。</p><p>asked 为谓语，me 为宾语，to place 为宾语补足语；执行 place 的人是 me。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>He told me don&#39;t touch it 应改为 He told me not to touch it；保留直接引语时则需引号和相应标点。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>朗读 asked me to open 与 asked me whether，辨认 to 后的动词和 whether 后的完整分句，不要将两种结构读成同一种停顿。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>The clerk asked me to open the outer carton. I explained that the glass bowls were gifts. She checked the label and thanked me for waiting.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>用三句描述一次包裹检查，包含一个要求和一个解释。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>要求用 to open，解释用 that 从句，两种转述结构作用不同。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>转述：She said to us, “Do not move the bags.”</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> She told us not to move the bags.</p><p><strong>解析：</strong> 否定命令用 not to do。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>例句里谁要放盒子？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 说话者本人，即 me。</p><p><strong>解析：</strong> 不定式动作的执行者由 asked 的宾语决定。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>填空：He asked me ___ I had a receipt.（whether/to）</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> whether</p><p><strong>解析：</strong> 后面是完整疑问内容的陈述语序。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：转述要求与否定命令。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-3/unit-01/grammar">单元语法</a> · <a href="/life/english/new-concept/book-3/unit-01/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-3/unit-01/review">单元自测</a></p><p><a href="/life/english/new-concept/book-3/unit-01/lesson-010">上一课</a> · <a href="/life/english/new-concept/book-3/unit-01/overview">单元目录</a> · <a href="/life/english/new-concept/book-3/unit-01/lesson-012">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const k=t(i,[["render",l]]);export{u as __pageData,k as default};
